for i,(f,layout,ends) in enumerate(zip(films,layouts,bookends)):
 R=Y/f['slug'];R.mkdir(exist_ok=True)
 for d in ['captures','sources','evidence','godot','excerpts','media','manim','mp3','exports','pantry']:(R/d).mkdir(exist_ok=True)
