 src='\n'.join(''.join(lines[n.lineno-1:n.end_lineno]) for n in tree.body if not isinstance(n,ast.ClassDef) or n.name in needed)
 src=src.replace(str(O),str(R))
 nt=ast.parse(new_scene_source);nl=new_scene_source.splitlines(True)
 src+='\n\n'+'\n\n'.join(''.join(nl[n.lineno-1:n.end_lineno]) for n in nt.body if not isinstance(n,ast.ClassDef) or n.name in needed)+'\n'
 (R/'scenes.py').write_text(src)
 # Exact contiguous excerpts, with a traceable map. Derived tree is labeled explicitly.
 em=json.loads((R/'evidence/excerpt-map.json').read_text())
 def excerpt(key,file,start,end):
  ll=(R/file).read_text().splitlines();a=next(j for j,l in enumerate(ll) if start in l);z=next(j for j in range(a,len(ll)) if end in ll[j]);(R/'excerpts'/f'{key}.txt').write_text('\n'.join(ll[a:z+1])+'\n');em.append({'key':key,'file':file,'start_line':a+1,'end_line':z+1,'kind':'exact contiguous excerpt'})
 (R/'excerpts/door-tree.txt').write_text('Door (Node2D)\n├── ApproachVisual (Polygon2D)\n├── Panel (Polygon2D)\n├── Solid (StaticBody2D)\n│   └── CollisionShape2D\n└── Approach (Area2D)\n    └── CollisionShape2D\n')
 em.append({'key':'door-tree','file':'godot/door.tscn','kind':'derived hierarchy; node names and types checked against saved scene'})
 excerpt('door-exports','godot/door.gd','signal approach_requested','var occupants:')
 excerpt('door-wiring','godot/comparison.gd','var packed := load','door.approach_requested.connect')
