 excerpt('door-occupancy','godot/door.gd','func close_when_clear()','return false')
 # Show occupancy insertion, removal and stale cleanup as selected exact source lines.
 ll=(R/'godot/door.gd').read_text().splitlines()
 chosen=[j for j,l in enumerate(ll) if any(t in l for t in ['func _entered(', 'occupants[actor.get_instance_id()]', 'func _exited(', 'occupants.erase(actor.get_instance_id())', 'for id in occupants.keys()', 'if occupants[id].get_ref()', 'occupants.erase(id)', 'if not occupants.is_empty()', 'return false'])]
 (R/'excerpts/door-occupancy.txt').write_text('\n'.join(ll[j] for j in chosen)+'\n')
