 excerpt('contact-monitor','godot/lab.gd','rb.contact_monitor=true','check("rigid contact reporting enabled"')
 # Short source excerpts avoid tiny text. Separate non-contiguous contact lines transparently.
 ll=(R/'godot/lab.gd').read_text().splitlines();chosen=[j for j,l in enumerate(ll) if any(x in l for x in ['rb.contact_monitor=true','rb.body_entered.connect','check("rigid contact reporting enabled"'])]
 (R/'excerpts/contact-monitor.txt').write_text('\n'.join(ll[j] for j in chosen)+'\n');em[-1]={'key':'contact-monitor','file':'godot/lab.gd','line_numbers':[j+1 for j in chosen],'kind':'selected source lines; intervening setup omitted'}
 (R/'evidence/excerpt-map.json').write_text(json.dumps(em,indent=2)+'\n')
 # Logs shown in shell scenes use recorded output, never invented terminal text.
 log=(R/'evidence/comparison-headless.log').read_text().splitlines()
 for key,needles in {'sensor-controls':['monitoring false','monitoring true','monitorable false','monitorable true'],'door-checks':['locked door refuses','opening disables','occupied door refuses','exit clears','closed shape restored']}.items():
  (R/'evidence'/f'{key}.txt').write_text('\n'.join(x for x in log if any(n in x for n in needles))+'\n')
 # Adapt the known sheet builder to per-film content.
 sh=(O/'make_sheet.py').read_text()
 sh=sh.replace("'Learn to organize objects, control interactions, and test motion.'","C['summary']") if False else sh
 sh=sh.replace("+'. Learn to organize objects, control interactions, and test motion.'","+'. '+C['summary']")
 a=sh.index("b=base('BIDEA'");z=sh.index(";b['lead_silence_s']",a);sh=sh[:a]+"b=base('BIDEA','Opening',C['intro'])"+sh[z:]
 sh=sh.replace("'text':'A game object is one physics problem','triggerWords':'one physics problem','replacementWords':'three different responsibilities'","'text':C['framing'],'triggerWords':C['trigger'],'replacementWords':C['replacement']")
 a=sh.index('terms=');z=sh.index('\nweb=',a)
 sh=sh[:a]+"terms=C['terms']\nb=base('BDEFS','Opening',' '.join(t+'. '+m for t,m in terms),gate='CARD');B.append(rem(b,'ClaudeDefinitions',{'title':'Terms In This Lecture','terms':[{'term':t,'meaning':m} for t,m in terms],'folderLabel':'@NikBearBrown'},'Terms arrive in spoken order'))\n"+sh[z:]
 sh=sh.replace('previous=-1',"for p in (R/'evidence').glob('*.txt'):\n shells.setdefault(p.stem,p.read_text().splitlines())\nprevious=-1")
 sh=sh.replace("else asset+' · source excerpt'","else 'Door hierarchy · derived from saved scene' if asset=='door-tree' else asset+' · source excerpt'")
